#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

Check K6: fail if an implementer commit changes a protected path.
A commit with no "Role:" trailer counts as an implementer commit. Human and agent commits follow
the same rule. Usage: protected_paths.py <base>
"""

import re
import subprocess
import sys

PROTECTED = [".claude/", ".cornerstone/", ".cornerstone/checks/", ".github/workflows/", "docs/specs/", "stone/tests/"]


def git(*args: str) -> str:
    return subprocess.run(["git", *args], check=True, capture_output=True, text=True).stdout


# The path match of paths.tests and paths.checks. The hook and K6 get the same text (D56).
# A value with no glob character uses the prefix rule: the path, or a path under that folder.
# A glob starts at the repo root. `*`, `?`, and `[...]` match inside one folder level. A `**`
# level matches any number of levels, also zero. A glob also covers each path under a folder
# that it matches. compile_path raises ValueError for a glob that is not valid.
GLOB_CHARS = "*?["


def _glob_level(level: str, pattern: str) -> str:
    out, i = "", 0
    while i < len(level):
        char = level[i]
        if char == "*":
            out += "[^/]*"
            while i + 1 < len(level) and level[i + 1] == "*":
                i += 1
        elif char == "?":
            out += "[^/]"
        elif char == "[":
            start = i + 1 + (level[i + 1:i + 2] == "!")
            end = level.find("]", start + (level[start:start + 1] == "]"))
            if end == -1:
                raise ValueError(f"'{pattern}' has a '[' with no ']'.")
            body = level[start:end].replace("\\", "\\\\").replace("^", "\\^")
            out += ("[^" if start > i + 1 else "[") + body + "]"
            i = end
        else:
            out += re.escape(char)
        i += 1
    return out


def compile_path(pattern: str):
    """Return the regex of a glob, or None for a value with no glob character."""
    if not any(char in pattern for char in GLOB_CHARS):
        return None
    if pattern.startswith("/"):
        raise ValueError(f"'{pattern}' starts with '/'. Write it relative to the repo root.")
    levels = pattern.rstrip("/").split("/")
    if pattern.endswith("/"):
        levels.append("**")
    out = ""
    for number, level in enumerate(levels):
        last = number == len(levels) - 1
        if level == "**":
            out += ".*" if last else "(?:[^/]+/)*"
        else:
            out += _glob_level(level, pattern) + ("" if last else "/")
    return re.compile(out)


def covers(patterns: list[str], path: str) -> bool:
    """True if a value in patterns covers the repo path (a path with '/' between the levels)."""
    levels = path.split("/")
    for pattern in patterns:
        regex = compile_path(pattern)
        if regex is None:
            folder = pattern.rstrip("/")
            if path == folder or path.startswith(folder + "/"):
                return True
        elif any(regex.fullmatch("/".join(levels[:n])) for n in range(1, len(levels) + 1)):
            return True
    return False


def main(base: str) -> int:
    failures = 0
    for sha in git("rev-list", "--no-merges", f"{base}..HEAD").split():
        roles = git("log", "-1", "--format=%(trailers:key=Role,valueonly)", sha).split()
        role = roles[-1].lower() if roles else "implementer"
        if role != "implementer":
            continue
        files = git("diff-tree", "--no-commit-id", "--name-only", "-r", sha).split("\n")
        for path in (file for file in files if covers(PROTECTED, file)):
            failures += 1
            print(f"K6: commit {sha[:12]} (Role: {role}) changes {path}, a protected path. "
                  "Revert the change. A test change belongs in a 'Role: tester' commit. A check "
                  "or CI change belongs in a human commit with its own 'Role:' trailer.")
    print(f"K6: {failures} finding(s).")
    return 1 if failures else 0


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: protected_paths.py <base>")
        sys.exit(2)
    sys.exit(main(sys.argv[1]))
